        elif opp_y < own_y:
            dy = -1
        # Prioritize close axis
        if abs(opp_x - own_x) > abs(opp_y - own_y):
            dy = 0
        elif abs(opp_y - own_y) > 0:
            dx = 0
    else:
        # Default movement: try to explore or hold position
        # Check if we can move in any direction
        for delta_x, delta_y in [(1,0), (-1,0), (0,1), (0,-1)]:
            new_x = own_x + delta_x
